args = sys.argv[1:]
show_guesses = "print" in args   # print every guess
use_dict = "dict" in args        # try the wordlist first

password = input("Enter password:")

# ── Shared state between threads ──
# A Lock stops two threads from touching the same variable at the exact same
# moment (a "race condition"). An Event is a flag every thread can see: once it
# is set, all threads know to stop.
lock = threading.Lock()
found_event = threading.Event()
result = {"password": None, "attempts": 0, "source": None}


def try_guess(guess, source):
    """Safely count the guess and report whether it is the password.

    Everything that touches shared state is done inside `with lock:` so only
    one thread can change it at a time — that is how the race is avoided.
    """
    with lock:
        result["attempts"] += 1
        if show_guesses:
            print(guess)

    if guess == password:
        with lock:
            # Only the first thread to get here records the win.
            if result["password"] is None:
                result["password"] = guess
                result["source"] = source
        found_event.set()   # tell every other thread to stop
        return True
    return False


# ── Step 1: dictionary (only in dict mode) ──
if use_dict and not found_event.is_set():
    here = os.path.dirname(os.path.abspath(__file__))
    wordlist = os.path.join(here, "phpbb.txt")
    with open(wordlist, encoding="latin-1") as f:
        for line in f:
            if found_event.is_set():
                break
            if try_guess(line.rstrip("\n"), "wordlist"):
                break


# ── Step 2: brute force, spread across several threads ──
def brute_worker(thread_index):
    chars = [chr(i) for i in range(32, 127)]  # space (32) to '~' (126)
    for length in range(1, MAX_LENGTH + 1):
        if found_event.is_set():
            return
        # Each thread owns a different slice of the first character, so no two
        # threads ever test the same guess.
        for first in chars[thread_index::NUM_THREADS]:
            if found_event.is_set():
                return
            for rest in itertools.product(chars, repeat=length - 1):
                if found_event.is_set():
                    return
                if try_guess(first + "".join(rest), "brute force"):
                    return


if not found_event.is_set():
    threads = [
        threading.Thread(target=brute_worker, args=(i,))
        for i in range(NUM_THREADS)
    ]
    for t in threads:
        t.start()
    for t in threads:
        t.join()   # wait for every thread to finish before reading the result


# ── Report (back on the main thread, so no locking needed here) ──
if result["password"] is not None:
    print("Password found:", result["password"])
    print("Took", result["attempts"], "guesses (" + result["source"] + ")")
else:
    print("Not found (try raising MAX_LENGTH)")
